const getRuntimeKV = `-- name: GetRuntimeKV :one
SELECT kv_value
FROM runtime.kv_store
WHERE kv_key = $1
  AND expires_at > now()
`

func (q *Queries) GetRuntimeKV(ctx context.Context, kvKey string) ([]byte, error) {
	row := q.db.QueryRow(ctx, getRuntimeKV, kvKey)
	var kv_value []byte
	err := row.Scan(&kv_value)
	return kv_value, err
}

const getSchemaVersion = `-- name: GetSchemaVersion :one
SELECT version
FROM public.schema_migrations
ORDER BY version DESC
LIMIT 1
`

func (q *Queries) GetSchemaVersion(ctx context.Context) (int32, error) {
	row := q.db.QueryRow(ctx, getSchemaVersion)
	var version int32
	err := row.Scan(&version)
	return version, err
}

