const insertDocumentPropertyClaim = `-- name: InsertDocumentPropertyClaim :exec
WITH run AS (
    INSERT INTO public.property_dimension_projection_runs (
        projection_type,
        projection_version,
        source_table,
        source_id,
        status,
        finished_at
    )
    VALUES (
        'source_claims',
        COALESCE(NULLIF($1, ''), 'document-llm-v1'),
        'property_documents',
        $3,
        'succeeded',
        now()
    )
    RETURNING property_dimension_projection_run_id
),
payload AS (
    SELECT
        public.fnc__legacy_property_dimension_target_type($9::text) AS target_type,
        public.fnc__legacy_property_dimension_claim_scope($9::text) AS claim_scope,
        public.fnc__legacy_property_dimension_key($10::text, $11::text) AS dimension_key,
        public.fnc__legacy_property_dimension_value_kind($12::text, $13::jsonb) AS value_kind,
        public.fnc__legacy_property_dimension_value($12::text, NULLIF($14, ''), $15::double precision, $16::boolean, $13::jsonb) AS value
)
INSERT INTO public.property_dimension_claims (
    property_dimension_projection_run_id,
    projection_version,
    claim_scope,
    target_type,
    target_id,
    dimension_key,
    value,
    value_kind,
    unit,
    source_table,
    source_id,
    source_field,
    source_observed_at,
    confidence,
    source_reliability,
    evidence,
    extraction_model,
    extraction_prompt_version
)
SELECT
    run.property_dimension_projection_run_id,
    COALESCE(NULLIF($1, ''), 'document-llm-v1'),
    payload.claim_scope,
    payload.target_type,
    $2,
    payload.dimension_key,
    payload.value,
    payload.value_kind,
    catalog.unit,
    'property_documents',
    $3,
    NULLIF($4, ''),
    COALESCE($5::timestamptz, now()),
    GREATEST(0, LEAST(1, $6::double precision / 100)),
    0.9,
    jsonb_build_object('text', NULLIF($7, '')),
    NULLIF($8, ''),
    NULLIF($1, '')
FROM run
CROSS JOIN payload
LEFT JOIN public.property_dimension_catalog catalog ON catalog.dimension_key = payload.dimension_key
WHERE payload.value IS NOT NULL
ON CONFLICT (
    claim_scope,
    target_type,
    target_id,
    dimension_key,
    source_table,
    source_id,
    COALESCE(source_field, ''),
    projection_version
) DO UPDATE SET
    value = EXCLUDED.value,
    value_kind = EXCLUDED.value_kind,
    unit = EXCLUDED.unit,
    source_observed_at = EXCLUDED.source_observed_at,
    confidence = EXCLUDED.confidence,
    source_reliability = EXCLUDED.source_reliability,
    evidence = EXCLUDED.evidence,
    extraction_model = EXCLUDED.extraction_model,
    extraction_prompt_version = EXCLUDED.extraction_prompt_version,
    updated_at = now()
`

